class Specialist:
    def __init__(self, name, topics):
        self.name, self.topics = name, topics
    def handle(self, message):
        return f"{self.name} agent handled: {message}"

billing = Specialist("billing", ["invoice", "refund", "charge"])
tech = Specialist("tech", ["error", "login", "crash"])

class Triage:                                 # the orchestrator agent
    def __init__(self, specialists):
        self.specialists = specialists
    def route(self, message):
        for agent in self.specialists:
            if any(t in message.lower() for t in agent.topics):
                return agent.handle(message)
        return "triage answered directly"

triage = Triage([billing, tech])
replies = [triage.route(m) for m in ["Refund my invoice", "App crash on login", "Hello"]]
print(replies)
